  const switchEnv = (value: string, discard = false) => { if (value === env) return; if (hasUnsavedDraft && !discard) { setPendingNavigation({kind:'environment',value}); return; } setEnv(value); setRevokeTarget(null); setKey(''); setSecret(''); setMessage(''); if (value === 'Production' && (!mfa || !approved)) setPage('Production readiness'); };
